$ErrorActionPreference='Stop'
$root=Join-Path $env:TEMP 'codebasegraph-cod56-11023706-4804-4438-b044-e9768538a0c8'
if(Test-Path -LiteralPath $root){throw 'Owned root already exists'}
[IO.Directory]::CreateDirectory($root)|Out-Null
[IO.File]::WriteAllText((Join-Path $root 'owner-receipt.txt'),'COD-56 bounded ARM64 supplement codebasegraph-cod56-11023706-4804-4438-b044-e9768538a0c8')
[IO.File]::WriteAllBytes((Join-Path $root 'candidate.ps1'),[Convert]::FromBase64String(''))
if((Get-FileHash (Join-Path $root 'candidate.ps1') -Algorithm SHA256).Hash -ne '830D128241C90B6F224554DC49BFCF572A1D51107DED8B12823E71D97C58B7BB'){throw 'Source hash mismatch candidate'}
[IO.File]::WriteAllBytes((Join-Path $root 'baseline.ps1'),[Convert]::FromBase64String(''))
if((Get-FileHash (Join-Path $root 'baseline.ps1') -Algorithm SHA256).Hash -ne 'BDD6F0EACE6FBD4EA25C9E09D2C6CB6C0B54A05955D024AA97D76443C58AE308'){throw 'Source hash mismatch baseline'}
$results=@()
foreach($variant in @('baseline','candidate')){
$p=Join-Path $root ($variant+'.ps1')
$tokens=$null;$errors=$null
$ast=[Management.Automation.Language.Parser]::ParseFile($p,[ref]$tokens,[ref]$errors)
$fn=@($ast.FindAll({param($n) $n -is [Management.Automation.Language.FunctionDefinitionAst] -and $n.Name -eq 'Assert-Binary'},$true))
if($fn.Count -ne 1){throw 'Expected exactly one Assert-Binary'}
$fpath=Join-Path $root ($variant+'-Assert-Binary.txt')
[IO.File]::WriteAllText($fpath,$fn[0].Extent.Text,(New-Object Text.UTF8Encoding($false)))
$results += [ordered]@{Variant=$variant;SourceSHA256=(Get-FileHash $p -Algorithm SHA256).Hash;ParseErrors=@($errors|ForEach-Object {$_.Message});ParseErrorCount=$errors.Count;FunctionSHA256=(Get-FileHash $fpath -Algorithm SHA256).Hash;FunctionBase64=[Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($fn[0].Extent.Text));FunctionStartLine=$fn[0].Extent.StartLineNumber;FunctionEndLine=$fn[0].Extent.EndLineNumber}
}
[ordered]@{Root=$root;Receipt=(Get-Content (Join-Path $root 'owner-receipt.txt'));Sources=$results}|ConvertTo-Json -Depth 8 -Compress
